17	/// Base class for Aggregation data that stores one of passed values: min, any, argMax...
18	/// It's setup as a virtual class so we can avoid templates when we need to extend them (argMax, SingleValueOrNull)
19	struct SingleValueDataBase
20	{
21	    /// Any subclass (numeric, string, generic) must be smaller than MAX_STORAGE_SIZE
22	    /// We use this knowledge to create composite data classes that use them directly by reserving a 'memory_block'
23	    /// For example argMin holds 1 of these (for the result), while keeping a template for the value
24	    static constexpr UInt32 MAX_STORAGE_SIZE = 64;
25	
26	    virtual ~SingleValueDataBase() = default;
27	    virtual bool has() const = 0;
28	    virtual void insertResultInto(IColumn &, const DataTypePtr & type) const = 0;
29	    virtual void write(WriteBuffer &, const ISerialization &) const = 0;
30	    virtual void read(ReadBuffer &, const ISerialization &, const DataTypePtr & type, Arena *) = 0;
31	
32	    virtual bool isEqualTo(const IColumn & column, size_t row_num) const = 0;
33	    virtual bool isEqualTo(const SingleValueDataBase &) const = 0;
34	    virtual void set(const IColumn &, size_t row_num, Arena *) = 0;
35	    virtual void set(const SingleValueDataBase &, Arena *) = 0;
36	    virtual bool setIfSmaller(const IColumn &, size_t row_num, Arena *) = 0;
37	    virtual bool setIfSmaller(const SingleValueDataBase &, Arena *) = 0;
38	    virtual bool setIfGreater(const IColumn &, size_t row_num, Arena *) = 0;
39	    virtual bool setIfGreater(const SingleValueDataBase &, Arena *) = 0;
40	
41	    /// Given a column, sets the internal value to the smallest or greatest value from the column
42	    /// Used to implement batch min/max
43	    virtual void setSmallest(const IColumn & column, size_t row_begin, size_t row_end, Arena * arena);
44	    virtual void setGreatest(const IColumn & column, size_t row_begin, size_t row_end, Arena * arena);
45	    virtual void setSmallestNotNullIf(const IColumn &, const UInt8 * __restrict, const UInt8 * __restrict, size_t, size_t, Arena *);
46	    virtual void setGreatestNotNullIf(const IColumn &, const UInt8 * __restrict, const UInt8 * __restrict, size_t, size_t, Arena *);
47	
48	    /// Given a column returns the index of the smallest or greatest value in it
49	    /// Doesn't return anything if the column is empty
50	    /// There are used to implement argMin / argMax
51	    virtual std::optional<size_t> getSmallestIndex(const IColumn & column, size_t row_begin, size_t row_end) const;
52	    virtual std::optional<size_t> getGreatestIndex(const IColumn & column, size_t row_begin, size_t row_end) const;
53	    virtual std::optional<size_t> getSmallestIndexNotNullIf(
54	        const IColumn & column, const UInt8 * __restrict null_map, const UInt8 * __restrict if_map, size_t row_begin, size_t row_end) const;
55	    virtual std::optional<size_t> getGreatestIndexNotNullIf(
56	        const IColumn & column, const UInt8 * __restrict null_map, const UInt8 * __restrict if_map, size_t row_begin, size_t row_end) const;
57	};
