19	/** The aggregate function 'singleValueOrNull' is used to implement subquery operators,
20	  * such as x = ALL (SELECT ...)
21	  * It checks if there is only one unique non-NULL value in the data.
22	  * If there is only one unique value - returns it.
23	  * If there are zero or at least two distinct values - returns NULL.
24	  */
25	
26	struct AggregateFunctionSingleValueOrNullData
27	{
28	    using Self = AggregateFunctionSingleValueOrNullData;
29	
30	private:
31	    SingleValueDataBaseMemoryBlock v_data;
32	    bool first_value = true;
33	    bool is_null = false;
34	
35	public:
36	    [[noreturn]] explicit AggregateFunctionSingleValueOrNullData()
37	    {
38	        throw Exception(ErrorCodes::LOGICAL_ERROR, "AggregateFunctionSingleValueOrNullData initialized empty");
39	    }
40	
41	    explicit AggregateFunctionSingleValueOrNullData(const DataTypePtr & value_type) { generateSingleValueFromType(value_type, v_data); }
42	
43	    ~AggregateFunctionSingleValueOrNullData() { data().~SingleValueDataBase(); }
44	
45	    SingleValueDataBase & data() { return v_data.get(); }
46	    const SingleValueDataBase & data() const { return v_data.get(); }
47	
48	    bool isNull() const { return is_null; }
49	
50	    void add(const IColumn & column, size_t row_num, Arena * arena)
51	    {
52	        if (first_value)
53	        {
54	            first_value = false;
55	            data().set(column, row_num, arena);
56	        }
57	        else if (!data().isEqualTo(column, row_num))
58	        {
59	            is_null = true;
60	        }
61	    }
62	
63	    void add(const Self & to, Arena * arena)
64	    {
65	        if (!to.data().has())
66	            return;
67	
68	        if (first_value && !to.first_value)
69	        {
70	            first_value = false;
71	            data().set(to.data(), arena);
72	        }
73	        else if (!data().isEqualTo(to.data()))
74	        {
75	            is_null = true;
76	        }
77	    }
78	
79	    /// TODO: Methods write and read lose data (first_value and is_null)
80	    /// Fixing it requires a breaking change (but it's probably necessary)
81	    void write(WriteBuffer & buf, const ISerialization & serialization) const { data().write(buf, serialization); }
82	
83	    void read(ReadBuffer & buf, const ISerialization & serialization, const DataTypePtr & data_type, Arena * arena) { data().read(buf, serialization, data_type, arena); }
84	
85	    void insertResultInto(IColumn & to, const DataTypePtr & result_type) const
86	    {
87	        if (is_null || first_value)
88	        {
89	            to.insertDefault();
90	        }
91	        else
92	        {
93	            ColumnNullable & col = typeid_cast<ColumnNullable &>(to);
94	            col.getNullMapColumn().insertDefault();
95	            data().insertResultInto(col.getNestedColumn(), result_type);
96	        }
97	    }
98	};
